SELECT stat_time, SUM(new_apply_cnt) AS new_apply_cnt, SUM(new_contact_cnt) AS new_contact_cnt, SUM(chat_cnt) AS chat_cnt, SUM(message_cnt) AS message_cnt, SUM(negative_feedback_cnt) AS negative_feedback_cnt, CASE WHEN SUM(chat_cnt) > 0 THEN SUM(reply_percentage * chat_cnt) / SUM(chat_cnt) END AS reply_percentage, CASE WHEN SUM(message_cnt) > 0 THEN (SUM(avg_reply_time * message_cnt) / SUM(message_cnt))::INTEGER END AS avg_reply_time FROM crm_wecom_behavior_daily WHERE stat_time BETWEEN #{startTime} AND #{endTime}
AND userid IN
#{uid}
GROUP BY stat_time ORDER BY stat_time

SELECT userid, MAX(user_name) AS name, SUM(new_apply_cnt) AS new_apply_cnt, SUM(new_contact_cnt) AS new_contact_cnt, SUM(chat_cnt) AS chat_cnt, SUM(message_cnt) AS message_cnt, SUM(negative_feedback_cnt) AS negative_feedback_cnt, CASE WHEN SUM(chat_cnt) > 0 THEN SUM(reply_percentage * chat_cnt) / SUM(chat_cnt) END AS reply_percentage, CASE WHEN SUM(message_cnt) > 0 THEN (SUM(avg_reply_time * message_cnt) / SUM(message_cnt))::INTEGER END AS avg_reply_time FROM crm_wecom_behavior_daily WHERE stat_time BETWEEN #{startTime} AND #{endTime}
AND userid IN
#{uid}
GROUP BY userid ORDER BY userid
